def check_dict_case(dict):
    if not dict:
        return False
    has_lower = has_upper = False
    for key in dict:
        if not isinstance(key, str):
            return False
        if key.islower():
            has_lower = True
        elif key.isupper():
            has_upper = True
        if has_lower and has_upper:
            return False
    return has_lower or has_upper
